sys_script_include.script:
var AggregateSerializer = Class.create();

AggregateSerializer.SCHEMA_VERSION = '1.0';

// Declarative aggregate trees. A child is { table, parent (field on the child
// that points at the parent row), as (JSON key), children }. Adding a child
// table to an export is one line here - nothing else changes.
AggregateSerializer.TREES = {
    submission: {
        table: 'SUBMISSION',
        children: [
            { table: 'SUBMISSION_LINE', parent: 'submission', as: 'lines', children: [
                { table: 'SUBMISSION_COVERAGE', parent: 'submission_line', as: 'coverages', children: [
                    { table: 'SUBMISSION_COVERAGE_TERM', parent: 'submission_coverage', as: 'terms' }
                ] }
            ] },
            { table: 'SUBMISSION_RISK', parent: 'submission', as: 'risks' },
            { table: 'SUBMISSION_PARTY', parent: 'submission', as: 'parties' },
            { table: 'LOSS_RECORD', parent: 'submission', as: 'losses' },
            { table: 'EXISTING_POLICY', parent: 'submission', as: 'existing_policies' },
            { table: 'CHANGE_SET', parent: 'submission', as: 'change_sets', children: [
                { table: 'CHANGE_ITEM', parent: 'change_set', as: 'items' }
            ] }
        ]
    },
    quote: {
        table: 'QUOTE',
        children: [
            { table: 'QUOTE_RISK', parent: 'quote', as: 'risks' },
            { table: 'QUOTE_OPTION', parent: 'quote', as: 'options', children: [
                { table: 'QUOTE_OPTION_LINE', parent: 'quote_option', as: 'lines', children: [
                    { table: 'COMMISSION', parent: 'quote_option_line', as: 'commissions' }
                ] },
                { table: 'QUOTE_OPTION_COVERAGE', parent: 'quote_option', as: 'coverages', children: [
                    { table: 'QUOTE_OPTION_COVERAGE_TERM', parent: 'quote_option_coverage', as: 'terms' },
                    { table: 'QUOTE_OPTION_COVERAGE_PERIL', parent: 'quote_option_coverage', as: 'perils' },
                    { table: 'QUOTE_OPTION_COVERAGE_EXCLUSION', parent: 'quote_option_coverage', as: 'exclusions' }
                ] },
                { table: 'QUOTE_TAX_FEE', parent: 'quote_option', as: 'taxes_fees' },
                { table: 'SUBJECTIVITY', parent: 'quote_option', as: 'subjectivities' }
            ] }
        ]
    },
    policy_version: {
        table: 'POLICY_VERSION',
        children: [
            { table: 'POLICY_PARTY', parent: 'policy_version', as: 'parties' },
            { table: 'POLICY_RISK', parent: 'policy_version', as: 'risks' },
            { table: 'POLICY_COVERAGE', parent: 'policy_version', as: 'coverages', children: [
                { table: 'POLICY_COVERAGE_TERM', parent: 'policy_coverage', as: 'terms' }
            ] },
            { table: 'POLICY_FORM', parent: 'policy_version', as: 'forms' },
            { table: 'COMMISSION', parent: 'policy_version', as: 'commissions' }
        ]
    },
    policy: {
        table: 'POLICY',
        children: [
            { table: 'POLICY_TERM', parent: 'policy', as: 'terms', children: [
                { table: 'POLICY_VERSION', parent: 'policy_term', as: 'versions' },
                { table: 'CLAIM', parent: 'policy_term', as: 'claims' }
            ] },
            { table: 'POLICY_TRANSACTION', parent: 'policy', as: 'transactions' }
        ]
    },
    product: {
        table: 'PRODUCT',
        children: [
            { table: 'PRODUCT_COVERAGE', parent: 'product', as: 'coverages', children: [
                { table: 'PRODUCT_COVERAGE_TERM', parent: 'product_coverage', as: 'terms' }
            ] },
            { table: 'PRODUCT_FORM', parent: 'product', as: 'forms' },
            { table: 'PRODUCT_ELIGIBILITY', parent: 'product', as: 'eligibility' },
            { table: 'PRODUCT_JURISDICTION', parent: 'product', as: 'jurisdictions' }
        ]
    }
};

AggregateSerializer.prototype = {

    initialize: function () {},

    // aggregate: key of TREES; sysId: root record. Returns the canonical object.
    serialize: function (aggregate, sysId) {
        var tree = AggregateSerializer.TREES[aggregate];
        if (!tree)
            throw new Error('[AggregateSerializer] unknown aggregate ' + aggregate);
        var root = new GlideRecord(Constants.TABLE[tree.table]);
        if (!root.get(sysId))
            return null;
        return {
            schema: 'policy_suite.' + aggregate,
            schema_version: AggregateSerializer.SCHEMA_VERSION,
            generated_on: new GlideDateTime().getValue().replace(' ', 'T') + 'Z',
            data: this._node(root, tree.children || [])
        };
    },

    toJson: function (aggregate, sysId) {
        return JSON.stringify(this.serialize(aggregate, sysId));
    },

    _node: function (gr, children) {
        var out = this._fields(gr);
        for (var i = 0; i < children.length; i++) {
            var c = children[i];
            var rows = [];
            var child = new GlideRecord(Constants.TABLE[c.table]);
            if (!child.isValid() || !child.isValidField(c.parent))
                continue;
            child.addQuery(c.parent, gr.getUniqueValue());
            child.orderBy('sys_created_on');
            child.query();
            while (child.next())
                rows.push(this._node(child, c.children || []));
            out[c.as] = rows;
        }
        return out;
    },

    // Codes, not labels. References carry the sys_id plus a display snapshot so
    // a consumer without access to our tables can still read the export.
    _fields: function (gr) {
        var out = { sys_id: gr.getUniqueValue() };
        var els = gr.getElements();
        for (var i = 0; i < els.length; i++) {
            var el = els[i];
            var name = el.getName();
            if (name.indexOf('sys_') === 0)
                continue;
            var ed = el.getED();
            var type = String(ed.getInternalType());
            var v = el.getValue();
            if (v === null || v === undefined || v === '')
                continue;
            if (type === 'reference')
                out[name] = { sys_id: String(v), display: String(el.getDisplayValue()) };
            else if (type === 'boolean')
                out[name] = String(v) === 'true' || String(v) === '1';
            else if (type === 'integer' || type === 'decimal' || type === 'float' || type === 'currency')
                out[name] = parseFloat(v);
            else if (type === 'glide_date_time')
                out[name] = String(v).replace(' ', 'T') + 'Z';
            else if (name === 'currency')
                out[name] = String(v).toUpperCase();    // ISO 4217 at the boundary; stored as a lower_snake_case token
            else
                out[name] = String(v);
        }
        return out;
    },

    type: 'AggregateSerializer'
};
